// Narration: pre-generated neural-voice audio (tools/gen_narration.py, edge-tts)
// with captions timed to its word boundaries. Lines without recorded audio
// (e.g. freshly generated by the AI) are synthesised on demand by the server
// (POST /api/tts: the same voice, word boundaries included) when it offers
// live narration (/api/providers says {tts: true}); otherwise, or when that
// fails, they are shown as captions only, unless the learner turns on the
// browser's own voice.
import { caption_cues, merge_recordings, narration_key, spoken_lang, to_spoken, tts_parts, type Cue, type Recording, type TtsReply } from '@mathnim/core';

/** A line ready to play: its word timing and its audio. */
interface Take {
  rec: Recording;
  src: string;
}

/** Every narrator alive on the page (lessons, the tutor's read-aloud), so a new page or step can silence them all. */
const alive = new Set<Narrator>();
/** Stop every narrator but `keep`: nothing goes on speaking over a page or step it does not belong to. */
export function hush_all(keep?: Narrator): void {
  for (const n of alive) if (n !== keep) n.stop(false);
}

export class Narrator {
  /** Play recorded narration. */
  enabled: boolean;
  /** Fall back to the browser's speech synthesis for lines without a recording. */
  system_voice: boolean;
  rate = 1;
  /** Keep the last line on screen when it has been said (a character's speech bubble). */
  keep_caption = false;
  /** Where recordings live (`<base>/<key>.json|mp3`). */
  base: string;
  /** Live narration endpoint (POST {text} -> TtsReply), or null to never use it. */
  live: string | null;
  private audio: HTMLAudioElement | null = null;
  /** The caption clock of the line playing (restarted when a seek brings back an ended line). */
  private tick: (() => void) | null = null;
  private raf = 0;
  private token = 0;
  private key = 'mathnim.narration';
  /** Called as the spoken phrase changes: the line's cues and the index being spoken (cues.length when done). */
  on_cue: ((cues: Cue[], index: number) => void) | null = null;

  constructor(private caption: HTMLElement, o: { base?: string; lang?: string; live?: string | null } = {}) {
    this.base = o.base ?? '/narration'; // absolute: lessons live at nested paths
    this.lang = o.lang ?? 'en-US';
    this.live = o.live === undefined ? '/api/tts' : o.live;
    let saved: { on?: boolean; system?: boolean } = {};
    try {
      saved = JSON.parse(localStorage.getItem(this.key) ?? '{}');
    } catch {
      /* no storage */
    }
    this.enabled = saved.on ?? true;
    this.system_voice = saved.system ?? false;
    alive.add(this);
  }
  lang: string;
  private persist(): void {
    try {
      localStorage.setItem(this.key, JSON.stringify({ on: this.enabled, system: this.system_voice }));
    } catch {
      /* no storage */
    }
  }
  set_enabled(on: boolean): void {
    this.enabled = on;
    this.persist();
    if (!on) this.stop(false);
  }
  set_rate(r: number): void {
    this.rate = r;
    if (this.audio) this.audio.playbackRate = r;
  }

  /** Show and speak a line. Resolves when it has finished (or was replaced). */
  async say(text: string): Promise<void> {
    if (this.dead) return;
    this.stop();
    const my = ++this.token;
    this.caption.textContent = text;
    if (!this.enabled) return;
    let take = await this.recording(text);
    if (!take && my === this.token && this.live) take = await live_take(this.live, text);
    if (my !== this.token) return;
    if (take) return this.play(take, text, my);
    if (this.system_voice && typeof speechSynthesis !== 'undefined') {
      const u = new SpeechSynthesisUtterance(to_spoken(text));
      u.lang = spoken_lang(text) === 'zh' ? 'zh-CN' : this.lang;
      u.rate = this.rate;
      speechSynthesis.speak(u);
    }
  }
  /** The pre-generated recording of a line, if there is one. */
  private async recording(text: string): Promise<Take | null> {
    const key = narration_key(text);
    try {
      const r = await fetch(`${this.base}/${key}.json`);
      // static hosts may answer a missing file with the app's HTML
      if (!r.ok || !(r.headers.get('content-type') ?? '').includes('json')) return null;
      return { rec: await r.json(), src: `${this.base}/${key}.mp3` };
    } catch {
      return null;
    }
  }
  private play(take: Take, text: string, my: number): Promise<void> {
    const { rec } = take;
    const cues = caption_cues(text, rec);
    const a = new Audio(take.src);
    a.playbackRate = this.rate;
    this.audio?.pause(); // (never two lines at once)
    this.audio = a;
    let shown = -1;
    const tick = () => {
      if (my !== this.token) return;
      const t = a.currentTime;
      let i = cues.findIndex((c) => t >= c.start && t < c.end);
      if (i < 0) i = cues.length - 1;
      if (i !== shown) {
        shown = i;
        this.caption.textContent = cues[i].text;
        this.on_cue?.(cues, i);
      }
      this.raf = requestAnimationFrame(tick);
    };
    this.tick = tick;
    return new Promise((resolve) => {
      a.onended = () => {
        cancelAnimationFrame(this.raf);
        if (my === this.token) this.on_cue?.(cues, cues.length);
        if (my === this.token && !this.keep_caption) setTimeout(() => my === this.token && (this.caption.textContent = ''), 1500);
        resolve();
      };
      a.play().then(tick, () => {
        // autoplay blocked until the first click: show the caption for its reading time instead
        if (!this.keep_caption) setTimeout(() => my === this.token && (this.caption.textContent = ''), (rec.duration + 1.5) * 1000);
        resolve();
      });
    });
  }
  /** Move the line to `t` seconds (the scene it goes with was seeked); past its end it stays quiet. */
  seek(t: number, playing: boolean): void {
    const a = this.audio;
    if (!a || !Number.isFinite(a.duration)) return;
    if (t >= a.duration) {
      a.pause();
      a.currentTime = a.duration;
      return;
    }
    a.currentTime = Math.max(0, t);
    if (playing && a.paused) {
      cancelAnimationFrame(this.raf);
      void a.play().then(() => this.tick?.(), () => {});
    } else if (!playing) a.pause();
  }
  pause(): void {
    this.audio?.pause();
    if (typeof speechSynthesis !== 'undefined') speechSynthesis.pause();
  }
  resume(): void {
    if (this.audio && this.audio.paused && !this.audio.ended) void this.audio.play();
    if (typeof speechSynthesis !== 'undefined') speechSynthesis.resume();
  }
  /** For good (the view is gone): stop, and ignore every later line. */
  dispose(): void {
    this.dead = true;
    this.stop();
    alive.delete(this);
  }
  private dead = false;
  stop(clear = true): void {
    this.token++;
    cancelAnimationFrame(this.raf);
    if (this.audio) {
      this.audio.pause();
      this.audio = null;
    }
    if (typeof speechSynthesis !== 'undefined') speechSynthesis.cancel();
    if (clear) this.caption.textContent = '';
  }
}

// ---------------------------------------------------------------- live narration (shared by all narrators on the page)
const PART_CHARS = 280; // longer lines are synthesised in parts, in parallel, and played back to back
const MAX_PARTS = 8;
const TIMEOUT_MS = 15_000;
const takes = new Map<string, Promise<Take | null>>(); // by narration key, most recent last
const TAKES_MAX = 40;
const available = new Map<string, Promise<boolean>>();
let failures = 0; // consecutive; after 3 the page stops asking

/** Does the server offer live narration? (asked once per page) */
function live_available(endpoint: string): Promise<boolean> {
  const url = endpoint.replace(/tts\/?$/, 'providers');
  let p = available.get(url);
  if (!p) {
    p = fetch(url)
      .then(async (r) => r.ok && (r.headers.get('content-type') ?? '').includes('json') && (await r.json()).tts === true)
      .catch(() => false);
    available.set(url, p);
  }
  return p;
}

async function live_take(endpoint: string, text: string): Promise<Take | null> {
  // the server reads it with the voice of its language (Yunxi for Chinese, Andrew for English)
  const lang = spoken_lang(text);
  if (failures >= 3 || !(await live_available(endpoint))) return null;
  const key = narration_key(text);
  let p = takes.get(key);
  if (p) {
    takes.delete(key); // refresh its place
  } else {
    const mine = (p = synthesize(endpoint, text, lang));
    void mine.then((t) => t || (takes.get(key) === mine && takes.delete(key))); // do not keep failures
  }
  takes.set(key, p);
  if (takes.size > TAKES_MAX) takes.delete(takes.keys().next().value!);
  return p;
}

async function synthesize(endpoint: string, text: string, lang: 'en' | 'zh'): Promise<Take | null> {
  const parts = tts_parts(text, PART_CHARS);
  if (!parts.length || parts.length > MAX_PARTS) return null;
  const replies = await Promise.all(parts.map((p) => fetch_part(endpoint, p, lang)));
  if (replies.some((r) => !r)) return null;
  const rs = replies as TtsReply[];
  if (rs.length === 1) return { rec: rs[0], src: `data:audio/mpeg;base64,${rs[0].audio}` };
  // MP3 frames concatenate: one audio element, word times shifted by the audio before them
  const bytes = rs.map((r) => Uint8Array.from(atob(r.audio), (c) => c.charCodeAt(0)));
  const all = new Uint8Array(bytes.reduce((n, b) => n + b.length, 0));
  let at = 0;
  for (const b of bytes) {
    all.set(b, at);
    at += b.length;
  }
  let bin = '';
  for (let i = 0; i < all.length; i += 0x8000) bin += String.fromCharCode(...all.subarray(i, i + 0x8000));
  return { rec: merge_recordings(text, rs), src: `data:audio/mpeg;base64,${btoa(bin)}` };
}

async function fetch_part(endpoint: string, text: string, lang: 'en' | 'zh'): Promise<TtsReply | null> {
  const ctl = new AbortController();
  const timer = setTimeout(() => ctl.abort(), TIMEOUT_MS);
  try {
    const r = await fetch(endpoint, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ text, lang }), signal: ctl.signal });
    if (r.ok) {
      failures = 0;
      return await r.json();
    }
    if (r.status >= 500 || r.status === 404 || r.status === 405) failures++; // 429 / 4xx: skip just this line
    return null;
  } catch {
    failures++;
    return null;
  } finally {
    clearTimeout(timer);
  }
}
